'use client';

import Link from 'next/link';
import { useEffect, useState } from 'react';
import { MenuItem, request, Vendor } from '../lib/api';

const types = ['ALL', 'VEG', 'NON_VEG', 'EGG', 'OTHER'];
const orderNext:any={PLACED:'ACCEPTED',ACCEPTED:'PREPARING',PREPARING:'READY',READY:'COMPLETED'};
const orderAction:any={PLACED:'ACCEPT',ACCEPTED:'PREPARE',PREPARING:'READY',READY:'COMPLETE'};

export default function VendorPortal() {
  const [token, setToken] = useState(''); const [vendor, setVendor] = useState<Vendor>();
  const [items, setItems] = useState<MenuItem[]>([]); const [tab, setTab] = useState<'menu' | 'orders'>('orders');
  const [filter, setFilter] = useState('ALL'); const [query, setQuery] = useState(''); const [availability, setAvailability] = useState('ALL'); const [menuOpen, setMenuOpen] = useState(false); const [mobile, setMobile] = useState('9999999999');
  const [otp, setOtp] = useState('123456'); const [error, setError] = useState('');
  async function load(session: string) { const [profile, menu] = await Promise.all([request<Vendor>('/api/vendor/me', {}, session), request<{items: MenuItem[]}>('/api/vendor/menu', {}, session)]); setVendor(profile); setItems(menu.items); }
  useEffect(() => { const saved = localStorage.getItem('foodcart.vendor') || ''; setToken(saved); if (saved) load(saved).catch(e => setError(e.message)); }, []);
  async function login() { try { setError(''); const auth = await request<{token:string}>('/api/auth/vendor/verify-otp', {method:'POST',body:JSON.stringify({mobile,otp})}); localStorage.setItem('foodcart.vendor', auth.token); setToken(auth.token); await load(auth.token); } catch (e:any) { setError(e.message); } }
  async function toggle(item: MenuItem) { const saved = await request<MenuItem>(`/api/vendor/menu/items/${item.id}/availability`, {method:'PATCH',body:JSON.stringify({available:!item.available})}, token); setItems(current => current.map(x => x.id === saved.id ? saved : x)); }
  async function remove(item: MenuItem) { if (!confirm(`Remove ${item.name} from your menu?`)) return; try { await request(`/api/vendor/menu/items/${item.id}`, {method:'DELETE'}, token); setItems(current => current.filter(x => x.id !== item.id)); } catch (e:any) { setError(e.message); } }
  if (!vendor) return <main className="vendor-frame"><section className="vendor-login"><p className="vendor-kicker">SUPR-MAMAL</p><h1>Built for every<br/>chef&apos;s counter.</h1><p>Sign in to manage your live menu and incoming orders.</p><label>VENDOR MOBILE<input value={mobile} maxLength={10} onChange={e=>setMobile(e.target.value.replace(/\D/g,''))}/></label><label>OTP <span>local: 123456</span><input value={otp} maxLength={6} onChange={e=>setOtp(e.target.value.replace(/\D/g,''))}/></label>{error&&<p className="vendor-error">{error}</p>}<button onClick={login}>CONTINUE</button></section></main>;
  const shown = items.filter(item => (filter === 'ALL' || item.foodType === filter) && (availability === 'ALL' || (availability === 'LIVE' ? item.available : !item.available)) && item.name.toLowerCase().includes(query.toLowerCase()));
  async function changeStoreStatus(){try{const saved=await request<Vendor>('/api/vendor/me/status',{method:'PATCH',body:JSON.stringify({status:vendor.status==='OPEN'?'CLOSED':'OPEN'})},token);setVendor(saved);}catch(e:any){setError(e.message)}}
  function logout(){localStorage.removeItem('foodcart.vendor');setVendor(undefined);setToken('');setMenuOpen(false);}
  return <main className="vendor-frame"><header className="vendor-top"><button aria-label="Open vendor menu" onClick={()=>setMenuOpen(x=>!x)}>☰</button><strong>{vendor.name}</strong><button title={vendor.status==='OPEN'?'Store is open — tap to close':'Store is closed — tap to open'} className="vendor-switch" onClick={changeStoreStatus}><i className={vendor.status==='OPEN'?'on':''}/></button></header>{menuOpen&&<aside className="vendor-drawer"><b>{vendor.name}</b><small>Store is {vendor.status==='OPEN'?'Open':'Closed'}</small><Link href="/">⌂ Customer homepage</Link><Link href="/vendor/settings">⚙ Store settings</Link><button onClick={logout}>↪ Log out</button></aside>}<section className="vendor-body">{tab==='menu'?<><div className="vendor-title"><div><small>MENU · LIVE CATALOGUE</small><h1>Your dishes</h1></div><Link href="/vendor/menu" className="vendor-add">+ Dish</Link></div><div className="vendor-tools"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search dishes"/><select value={availability} onChange={e=>setAvailability(e.target.value)}><option value="ALL">All status</option><option value="LIVE">Live only</option><option value="SOLD_OUT">Sold out</option></select></div><div className="vendor-filters">{types.map(type=><button key={type} onClick={()=>setFilter(type)} className={filter===type?'active':''}>{type.replace('_',' ')}</button>)}</div><div className="vendor-menu-list">{shown.map(item=><article key={item.id} className="vendor-dish">{item.imageUrl?<img src={item.imageUrl} alt=""/>:<div className="vendor-image-placeholder"/>}<div><b><span className={item.foodType==='VEG'?'veg-dot':'nonveg-dot'}/> {item.name}</b><p>{item.description||'Freshly prepared at the counter'}</p><strong>₹{item.price}</strong></div><div className="dish-actions"><button onClick={()=>toggle(item)} className={item.available?'availability':'availability off'}>{item.available?'ON':'OFF'}</button><button onClick={()=>remove(item)} className="remove-dish">REMOVE</button></div></article>)}{shown.length===0&&<p className="vendor-empty">No dishes match these filters.</p>}</div></>:<Orders token={token}/>}</section><nav className="vendor-bottom"><button className={tab==='menu'?'selected':''} onClick={()=>setTab('menu')}>▣ <span>Menu</span></button><button className={tab==='orders'?'selected':''} onClick={()=>setTab('orders')}>🛒 <span>Orders</span></button></nav></main>;
}

function Orders({token}:{token:string}) { const [orders,setOrders]=useState<any[]>([]); const [query,setQuery]=useState(''); const [status,setStatus]=useState('ALL'); const [offset,setOffset]=useState(0); useEffect(()=>{request<any[]>('/api/vendor/orders',{},token).then(setOrders);},[token]); async function advance(order:any,event:any){event.stopPropagation();const saved=await request<any>(`/api/vendor/orders/${order.id}/status`,{method:'PATCH',body:JSON.stringify({status:orderNext[order.status]})},token);setOrders(all=>all.map(x=>x.id===saved.id?saved:x));}const day=new Date();day.setHours(0,0,0,0);day.setDate(day.getDate()+offset);const title=offset===0?"TODAY'S ORDERS":day.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}).toUpperCase();const shown=orders.filter(order=>{const created=order.createdAt?new Date(order.createdAt):new Date();const sameDay=created.getFullYear()===day.getFullYear()&&created.getMonth()===day.getMonth()&&created.getDate()===day.getDate();return sameDay&&(status==='ALL'||order.status===status)&&(`${order.orderNumber} ${order.customerMobile||''} ${order.items?.map((item:any)=>item.name).join(' ')||''}`).toLowerCase().includes(query.toLowerCase())});return <><div className="vendor-date"><button onClick={()=>setOffset(x=>x-1)} aria-label="Previous day">‹</button><b>{title}</b><button onClick={()=>setOffset(x=>x+1)} aria-label="Next day">›</button></div><div className="vendor-tools"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search order or customer"/><select value={status} onChange={e=>setStatus(e.target.value)}><option value="ALL">All orders</option><option value="PLACED">New</option><option value="ACCEPTED">Accepted</option><option value="PREPARING">Preparing</option><option value="READY">Ready</option><option value="COMPLETED">Completed</option><option value="REJECTED">Rejected</option></select></div><div className="vendor-order-list">{shown.map(order=><article className="vendor-order vendor-order-click" key={order.id} onClick={()=>window.location.href=`/vendor/orders?id=${order.id}`}><div><b>#{order.orderNumber}</b><span>{order.status.replace('_',' ')}</span></div><a>☎ {order.customerMobile||'Customer'}</a><p>{order.items?.map((item:any)=>`${item.quantity}× ${item.name}`).join(' · ')}</p><footer><b>₹{order.total}</b>{orderAction[order.status]?<button onClick={event=>advance(order,event)}>{orderAction[order.status]}</button>:<small>VIEW DETAILS →</small>}</footer></article>)}{shown.length===0&&<p className="vendor-empty">No orders match this date and filter.</p>}</div></>; }
